  1→import { notFound } from "next/navigation";
  2→import Image from "next/image";
  3→import { PROJECTS, getProject, CASE_STUDIES } from "@/lib/projects";
  4→import { CaseStudySection } from "@/components/CaseStudySection";
  5→import { ImageGallery } from "@/components/ImageGallery";
  6→import { heroImage, detailImages } from "@/lib/images";
  7→import Link from "next/link";
  8→import type { Metadata } from "next";
  9→
 10→const BackArrow = (
 11→  <svg width="14" height="14" viewBox="0 0 14 14" fill="none" stroke="currentColor" strokeWidth="1.5">
 12→    <path d="M8 1L2 7L8 13" />
 13→  </svg>
 14→);
 15→
 16→interface PageProps {
 17→  params: Promise<{ slug: string }>;
 18→}
 19→
 20→export async function generateStaticParams() {
 21→  return PROJECTS.map((p) => ({ slug: p.slug }));
 22→}
 23→
 24→export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
 25→  const { slug } = await params;
 26→  const project = getProject(slug);
 27→  if (!project) return {};
 28→  return {
 29→    title: project.title,
 30→    description: project.desc,
 31→    openGraph: {
 32→      images: [`/images/${project.slug}/hero.jpg`],
 33→    },
 34→  };
 35→}
 36→
 37→export default async function ProjectPage({ params }: PageProps) {
 38→  const { slug } = await params;
 39→  const project = getProject(slug);
 40→  if (!project) notFound();
 41→
 42→  const caseStudy = CASE_STUDIES[project.slug];
 43→  const hero = heroImage(project.slug);
 44→  const details = detailImages(project.slug);
 45→  const idx = PROJECTS.findIndex((p) => p.slug === project.slug);
 46→  const prev = idx > 0 ? PROJECTS[idx - 1] : null;
 47→  const next = idx < PROJECTS.length - 1 ? PROJECTS[idx + 1] : null;
 48→
 49→  return (
 50→    <div style={{ paddingTop: "var(--nav-h)" }}>
 51→      {/* Back link */}
 52→      <div style={{ maxWidth: "var(--max-w)", margin: "0 auto", padding: "clamp(24px, 4vh, 40px) var(--pad) 0" }}>
 53→        <Link href="/work" className="link-muted" style={{ fontSize: 13, letterSpacing: "0.06em", textTransform: "uppercase", display: "inline-flex", alignItems: "center", gap: 8 }}>
 54→          {BackArrow}
 55→          All Work
 56→        </Link>
 57→      </div>
 58→
 59→      {/* Header */}
 60→      <div style={{ padding: "clamp(32px, 6vh, 64px) var(--pad) clamp(48px, 6vh, 80px)", maxWidth: "var(--max-w)", margin: "0 auto" }}>
 61→        <h1 style={{ fontSize: "clamp(36px, 4.5vw, 64px)", fontWeight: 400, letterSpacing: "-0.02em", color: "var(--text)", margin: "0 0 24px", lineHeight: 1.05 }}>
 62→          {project.title}
 63→        </h1>
 64→        <div style={{ display: "flex", gap: "clamp(40px, 6vw, 120px)", alignItems: "flex-start", flexWrap: "wrap" }}>
 65→          <p style={{ fontSize: "clamp(16px, 1.4vw, 20px)", fontWeight: 400, color: "var(--muted)", lineHeight: 1.6, margin: 0, maxWidth: 540, flex: "1 1 360px" }}>
 66→            {project.longDesc || project.desc}
 67→          </p>
 68→          <div style={{ flex: "0 0 180px" }}>
 69→            {[
 70→              { label: "Role", value: "Brand Design Director" },
 71→              { label: "Discipline", value: project.category },
 72→              ...(project.credits ? [{ label: "Credits", value: project.credits }] : []),
 73→            ].map((item) => (
 74→              <div key={item.label} style={{ marginBottom: 18 }}>
 75→                <div style={{ fontSize: 11, color: "var(--muted-light)", fontWeight: 400, letterSpacing: "0.06em", textTransform: "uppercase", marginBottom: 3 }}>
 76→                  {item.label}
 77→                </div>
 78→                <div style={{ fontSize: 14, color: "var(--text)", fontWeight: 400, lineHeight: 1.4 }}>
 79→                  {item.value}
 80→                </div>
 81→              </div>
 82→            ))}
 83→          </div>
 84→        </div>
 85→      </div>
 86→
 87→      {/* Hero image -- natural aspect ratio, full width */}
 88→      {hero && (
 89→        <div style={{ maxWidth: "var(--max-w)", margin: "0 auto", padding: "0 var(--pad)" }}>
 90→          <Image
 91→            src={hero}
 92→            alt={project.heroAlt || project.title}
 93→            width={2400}
 94→            height={1600}
 95→            style={{ width: "100%", height: "auto", borderRadius: "var(--img-radius)" }}
 96→            sizes="(max-width: 768px) 100vw, (max-width: 1400px) 90vw, 1400px"
 97→            priority
 98→          />
 99→        </div>
100→      )}
101→
102→      {/* Video embed */}
103→      {project.videoUrl && (
104→        <div style={{ maxWidth: "var(--max-w)", margin: "40px auto 0", padding: "0 var(--pad)" }}>
105→          <div style={{ position: "relative", paddingBottom: "56.25%", height: 0, overflow: "hidden", borderRadius: "var(--img-radius)" }}>
106→            <iframe
107→              src={project.videoUrl}
108→              style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%", border: 0 }}
109→              allow="autoplay; fullscreen; picture-in-picture"
110→              allowFullScreen
111→              title={project.title}
112→            />
113→          </div>
114→        </div>
115→      )}
116→
117→      {/* Case study or gallery -- single column, natural aspect ratios */}
118→      <div style={{ maxWidth: "var(--max-w)", margin: "0 auto", padding: "0 var(--pad)" }}>
119→        {caseStudy ? (
120→          caseStudy.sections.map((section, si) => {
121→            // Compute cumulative offset from previous sections' image counts
122→            const offset = caseStudy.sections
123→              .slice(0, si)
124→              .reduce((sum, s) => sum + (s.images || 2), 0);
125→            const sectionImages = details.slice(offset, offset + (section.images || 2));
126→            return (
127→              <CaseStudySection key={si} section={section} sectionIndex={si} title={project.title} images={sectionImages} />
128→            );
129→          })
130→        ) : details.length > 0 ? (
131→          <ImageGallery images={details} alt={project.title} />
132→        ) : null}
133→      </div>
134→
135→      {/* Prev/Next navigation */}
136→      <div style={{ maxWidth: "var(--max-w)", margin: "60px auto 0", padding: "0 var(--pad)", display: "flex", justifyContent: "space-between", borderTop: "1px solid var(--border)", paddingTop: 32 }}>
137→        {prev ? (
138→          <Link href={`/work/${prev.slug}`} className="hover-dim" style={{ fontSize: 16, color: "var(--text)" }}>
139→            <span style={{ fontSize: 11, color: "var(--muted)", letterSpacing: "0.08em", textTransform: "uppercase", display: "block", marginBottom: 4 }}>Previous</span>
140→            {prev.title}
141→          </Link>
142→        ) : <div />}
143→        {next ? (
144→          <Link href={`/work/${next.slug}`} className="hover-dim" style={{ fontSize: 16, color: "var(--text)", textAlign: "right" }}>
145→            <span style={{ fontSize: 11, color: "var(--muted)", letterSpacing: "0.08em", textTransform: "uppercase", display: "block", marginBottom: 4 }}>Next</span>
146→            {next.title}
147→          </Link>
148→        ) : <div />}
149→      </div>
150→
151→      <div style={{ height: 60 }} />
152→    </div>
153→  );
154→}
