  3→import { useState, useEffect } from "react";
  4→import Link from "next/link";
  5→import { usePathname } from "next/navigation";
  6→import styles from "./Nav.module.css";
  7→
  8→const NAV_LINKS = [
  9→  { href: "/work", label: "Work" },
 10→  { href: "/about", label: "About" },
 11→] as const;
 12→
 13→const SOCIAL_LINKS = [
 14→  { label: "LinkedIn", href: "https://www.linkedin.com/in/jaimeibrahim/" },
 15→] as const;
 16→
 17→export function Nav() {
 18→  const pathname = usePathname();
 19→  const [scrolled, setScrolled] = useState(false);
 20→  const [mobileOpen, setMobileOpen] = useState(false);
 21→
 22→  // Close mobile menu on route change
 23→  useEffect(() => {
 24→    // eslint-disable-next-line react-hooks/set-state-in-effect -- Intentional: close menu on navigation
 25→    setMobileOpen(false);
 26→  }, [pathname]);
 27→
 28→  useEffect(() => {
 29→    const handler = () => setScrolled(window.scrollY > 20);
 30→    window.addEventListener("scroll", handler, { passive: true });
 31→    return () => window.removeEventListener("scroll", handler);
 32→  }, []);
 33→
 34→  const isActive = (href: string) => {
 35→    if (href === "/work") return pathname === "/" || pathname.startsWith("/work");
 36→    return pathname.startsWith(href);
 37→  };
 38→
 39→  return (
 40→    <nav className={`${styles.nav} ${scrolled ? styles.navScrolled : ""}`}>
 41→      {/* Left: nav links */}
 42→      <div className={`${styles.links} ${styles.linksLeft}`}>
 43→        {NAV_LINKS.map((link) => (
 44→          <Link key={link.href} href={link.href} className={`${styles.navLink} ${isActive(link.href) ? styles.navLinkActive : ""}`}>
 45→            {link.label}
 46→          </Link>
 47→        ))}
 48→      </div>
 49→
 50→      {/* Center: nameplate — full reload to replay intro */}
 51→      <a
 52→        href="/"
 53→        className={styles.nameplate}
 54→        onClick={(e) => {
 55→          e.preventDefault();
 56→          try { sessionStorage.removeItem("jaime-intro-played"); } catch {}
 57→          window.location.href = "/";
 58→        }}
 59→      >
 60→        <span className={styles.hairline} />
 61→        <span className={styles.nameplateText}>Jaime Ibrahim</span>
 62→        <span className={styles.hairline} />
 63→      </a>
 64→
 65→      {/* Right: social links */}
 66→      <div className={`${styles.links} ${styles.linksRight}`}>
 67→        {SOCIAL_LINKS.map((link) => (
 68→          <a
 69→            key={link.label}
 70→            href={link.href}
 71→            target="_blank"
 72→            rel="noopener noreferrer"
 73→            className={styles.navLink}
 74→          >
 75→            {link.label}
 76→          </a>
 77→        ))}
 78→      </div>
 79→
 80→      {/* Mobile menu button */}
 81→      <button
 82→        className={styles.mobileMenuBtn}
 83→        onClick={() => setMobileOpen(!mobileOpen)}
 84→        aria-label="Toggle menu"
 85→      >
 86→        <span
 87→          className={styles.mobileMenuLine}
 88→          style={{
 89→            transform: mobileOpen ? "rotate(45deg) translate(2px, 2px)" : "none",
 90→          }}
 91→        />
 92→        <span
 93→          className={styles.mobileMenuLine}
 94→          style={{ opacity: mobileOpen ? 0 : 1 }}
 95→        />
 96→        <span
 97→          className={styles.mobileMenuLine}
 98→          style={{
 99→            transform: mobileOpen ? "rotate(-45deg) translate(2px, -2px)" : "none",
100→          }}
101→        />
102→      </button>
103→
104→      {/* Mobile dropdown */}
105→      {mobileOpen && (
106→        <div className={styles.mobileDropdown}>
107→          {NAV_LINKS.map((link) => (
108→            <Link
109→              key={link.href}
110→              href={link.href}
111→              className={`${styles.mobileLink} ${isActive(link.href) ? styles.mobileLinkActive : ""}`}
112→            >
113→              {link.label}
114→            </Link>
115→          ))}
116→          <div className={styles.mobileSocials}>
117→            {SOCIAL_LINKS.map((link) => (
118→              <a
119→                key={link.label}
120→                href={link.href}
121→                target="_blank"
122→                rel="noopener noreferrer"
123→                className={styles.mobileSocialLink}
124→              >
125→                {link.label}
126→              </a>
127→            ))}
128→          </div>
129→        </div>
130→      )}
131→    </nav>
132→  );
133→}
