14→export function Footer() {
15→  const [hovered, setHovered] = useState(false);
16→  const [weather, setWeather] = useState<{ temp: number; icon: string } | null>(null);
17→
18→  useEffect(() => {
19→    const fetchWeather = () => {
20→      fetch("https://api.open-meteo.com/v1/forecast?latitude=40.7128&longitude=-74.006&current=temperature_2m,weather_code&temperature_unit=fahrenheit")
21→        .then((r) => r.json())
22→        .then((d) => {
23→          if (d.current) {
24→            const temp = Math.round(d.current.temperature_2m);
25→            const code = d.current.weather_code;
26→            let icon = "Clear";
27→            if (code === 0) icon = "Clear";
28→            else if (code <= 3) icon = "Partly cloudy";
29→            else if (code <= 48) icon = "Cloudy";
30→            else if (code <= 67) icon = "Rain";
31→            else if (code <= 77) icon = "Snow";
32→            else if (code <= 82) icon = "Rain";
33→            else if (code <= 86) icon = "Snow";
34→            else icon = "Storm";
35→            setWeather({ temp, icon });
36→          }
37→        })
38→        .catch(() => {});
39→    };
40→    // Defer weather fetch so it doesn't compete with LCP resources
41→    if ("requestIdleCallback" in window) {
42→      const id = requestIdleCallback(fetchWeather);
43→      return () => cancelIdleCallback(id);
44→    } else {
45→      const id = setTimeout(fetchWeather, 2000);
46→      return () => clearTimeout(id);
47→    }
48→  }, []);
49→
50→  return (
51→    <footer style={{ position: "relative", zIndex: 1 }}>
52→      <div
53→        className={styles.ctaBlock}
54→        onMouseEnter={() => setHovered(true)}
55→        onMouseLeave={() => setHovered(false)}
56→      >
57→        <Link href="/about" style={{ display: "block", cursor: "pointer" }}>
58→          <p className={styles.ctaText} style={{ color: hovered ? "var(--muted)" : "var(--text)" }}>
59→            Let&apos;s Work Together
60→          </p>
61→        </Link>
62→        <p className={styles.ctaEmail}>
63→          <a href="https://www.linkedin.com/in/jaimeibrahim/" target="_blank" rel="noopener noreferrer" style={{ color: "inherit" }}>
64→            Connect on LinkedIn
65→          </a>
66→        </p>
67→      </div>
68→
69→      <div className={styles.infoBar}>
70→        <span className={styles.socials}>
71→          <a href="https://www.linkedin.com/in/jaimeibrahim/" target="_blank" rel="noopener noreferrer" className={styles.socialLink} aria-label="LinkedIn">
72→            {LinkedInIcon}
73→          </a>
74→        </span>
75→        <span className={styles.copyright}>
76→          &copy; 2026 Jaime Ibrahim &nbsp;&nbsp;|&nbsp;&nbsp; Brand Design Director &nbsp;&nbsp;|&nbsp;&nbsp; New York City
77→          {weather && (
78→            <span style={{ opacity: 0.5, fontSize: 11 }}>
79→              &nbsp;&nbsp;{weather.icon} {weather.temp}&deg;F
80→            </span>
81→          )}
82→        </span>
83→      </div>
84→    </footer>
85→  );
86→}
