 1→"use client";
 2→
 3→import { useRef, useEffect, useState } from "react";
 4→import Link from "next/link";
 5→import Image from "next/image";
 6→import { PlaceholderImage } from "./PlaceholderImage";
 7→import { MetaTag } from "./MetaTag";
 8→import { heroImage } from "@/lib/images";
 9→import type { Project } from "@/lib/types";
10→import styles from "./GridCard.module.css";
11→
12→interface GridCardProps {
13→  project: Project;
14→  showText: boolean;
15→  height: number;
16→  columnIndex?: number;
17→}
18→
19→export function GridCard({ project, showText, height, columnIndex = 0 }: GridCardProps) {
20→  const hero = heroImage(project.slug);
21→  const cardRef = useRef<HTMLAnchorElement>(null);
22→  const [revealed, setRevealed] = useState(false);
23→
24→  useEffect(() => {
25→    const el = cardRef.current;
26→    if (!el) return;
27→
28→    // Respect reduced motion
29→    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
30→    if (mq.matches) {
31→      setRevealed(true);
32→      return;
33→    }
34→
35→    const observer = new IntersectionObserver(
36→      ([entry]) => {
37→        if (entry.isIntersecting) {
38→          setRevealed(true);
39→          observer.disconnect();
40→        }
41→      },
42→      { threshold: 0.15 }
43→    );
44→    observer.observe(el);
45→    return () => observer.disconnect();
46→  }, []);
47→
48→  return (
49→    <Link
50→      ref={cardRef}
51→      href={`/work/${project.slug}`}
52→      className={`${styles.card} ${revealed ? styles.cardRevealed : ""}`}
53→      style={{ "--reveal-delay": `${columnIndex * 180}ms` } as React.CSSProperties}
54→    >
55→      {/* Image */}
56→      <div className={styles.imageContainer}>
57→        <div className={styles.imageInner}>
58→          {hero ? (
59→            <div style={{ position: "relative", width: "100%", height }}>
60→              <Image
61→                src={hero}
62→                alt={project.heroAlt || project.title}
63→                fill
64→                style={{ objectFit: "cover", objectPosition: project.cropPosition || "center" }}
65→                sizes="(max-width: 768px) 100vw, (max-width: 1400px) 66vw, 900px"
