 14→export function IntroAnimation() {
 15→  const [phase, setPhase] = useState<
 16→    "check" | "playing" | "fadeOut" | "done"
 17→  >("check");
 18→  const [nameVisible, setNameVisible] = useState(false);
 19→
 20→  const skipIntro = useCallback(() => {
 21→    setPhase("done");
 22→    try {
 23→      sessionStorage.setItem(SESSION_KEY, "1");
 24→    } catch {
 25→      // sessionStorage unavailable
 26→    }
 27→  }, []);
 28→
 29→  useEffect(() => {
 30→    // Check if already played this session
 31→    try {
 32→      if (sessionStorage.getItem(SESSION_KEY)) {
 33→        setPhase("done");
 34→        return;
 35→      }
 36→    } catch {
 37→      // sessionStorage unavailable, play anyway
 38→    }
 39→
 40→    // Check reduced motion preference
 41→    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
 42→      skipIntro();
 43→      return;
 44→    }
 45→
 46→    setPhase("playing");
 47→
 48→    // Name reveals
 49→    const t1 = setTimeout(() => setNameVisible(true), T_NAME);
 50→    // Fade out overlay
