 5→export function ScrollProgress() {
 6→  const barRef = useRef<HTMLDivElement>(null);
 7→  const wrapperRef = useRef<HTMLDivElement>(null);
 8→
 9→  useEffect(() => {
10→    const handler = () => {
11→      const docHeight = document.documentElement.scrollHeight - window.innerHeight;
12→      const pct = docHeight > 0 ? Math.min(1, Math.max(0, window.scrollY / docHeight)) : 0;
13→      if (barRef.current) {
14→        barRef.current.style.transform = `scaleX(${pct})`;
15→      }
16→      if (wrapperRef.current) {
17→        wrapperRef.current.style.display = pct < 0.01 ? "none" : "block";
18→      }
19→    };
20→    window.addEventListener("scroll", handler, { passive: true });
21→    return () => window.removeEventListener("scroll", handler);
22→  }, []);
23→
24→  return (
25→    <div ref={wrapperRef} style={{ position: "fixed", top: 0, left: 0, right: 0, height: 2, zIndex: 200, display: "none" }}>
26→      <div
27→        ref={barRef}
28→        style={{
29→          height: "100%",
30→          background: "var(--text)",
31→          opacity: 0.15,
32→          transform: "scaleX(0)",
