  3→
  4→/**
  5→ * Gretel-inspired image layout.
  6→ * Arranges images in a rhythm: full-width → asymmetric pair → full-width → flipped pair...
  7→ * This creates visual variety instead of uniform single-column stacking.
  8→ */
  9→
 10→type LayoutRow =
 11→  | { type: "full"; images: string[] }
 12→  | { type: "wide-narrow"; images: string[] }
 13→  | { type: "narrow-wide"; images: string[] };
 14→
 15→function buildLayout(images: string[]): LayoutRow[] {
 16→  const rows: LayoutRow[] = [];
 17→  let i = 0;
 18→  let pairFlip = false;
 19→
 20→  while (i < images.length) {
 21→    const remaining = images.length - i;
 22→
 23→    if (remaining === 1) {
 24→      // Last image always full-width
 25→      rows.push({ type: "full", images: [images[i]] });
 26→      i += 1;
 27→    } else if (remaining === 2) {
 28→      // Last two: make a pair
 29→      rows.push({
 30→        type: pairFlip ? "narrow-wide" : "wide-narrow",
 31→        images: [images[i], images[i + 1]],
 32→      });
 33→      i += 2;
 34→    } else if (remaining === 3) {
 35→      // Three left: full + pair (avoids orphan)
 36→      rows.push({ type: "full", images: [images[i]] });
 37→      rows.push({
 38→        type: pairFlip ? "narrow-wide" : "wide-narrow",
 39→        images: [images[i + 1], images[i + 2]],
 40→      });
 41→      i += 3;
 42→    } else {
 43→      // 4+: alternate full → pair
 44→      rows.push({ type: "full", images: [images[i]] });
 45→      i += 1;
 46→      rows.push({
 47→        type: pairFlip ? "narrow-wide" : "wide-narrow",
 48→        images: [images[i], images[i + 1]],
 49→      });
 50→      pairFlip = !pairFlip;
 51→      i += 2;
 52→    }
 53→  }
 54→
 55→  return rows;
 56→}
