 3→import { useState, useEffect, useRef, type RefObject } from "react";
 4→
 5→interface UseInViewOptions {
 6→  threshold?: number;
 7→  rootMargin?: string;
 8→}
 9→
10→export function useInView(options: UseInViewOptions = {}): [RefObject<HTMLDivElement | null>, boolean] {
11→  const ref = useRef<HTMLDivElement | null>(null);
12→  const [inView, setInView] = useState(false);
13→
14→  useEffect(() => {
15→    const el = ref.current;
16→    if (!el) return;
17→    const observer = new IntersectionObserver(
18→      ([entry]) => {
19→        if (entry.isIntersecting) {
20→          setInView(true);
21→          observer.unobserve(el);
22→        }
23→      },
24→      {
25→        threshold: options.threshold ?? 0.15,
26→        rootMargin: options.rootMargin ?? "0px 0px -10% 0px",
27→      }
28→    );
29→    observer.observe(el);
30→    return () => observer.disconnect();
31→  }, [options.threshold, options.rootMargin]);
32→
33→  return [ref, inView];
34→}
