 23→/* --- Domino reveal (IO-triggered) --- */
 24→
 25→.imageInner {
 26→  clip-path: inset(0 0 100% 0);
 27→  opacity: 0;
 28→  transform: scale(1.05);
 29→  transition:
 30→    clip-path 700ms var(--ease-out) var(--reveal-delay, 0ms),
 31→    opacity 600ms var(--ease-out) var(--reveal-delay, 0ms),
 32→    transform 800ms var(--ease-out) var(--reveal-delay, 0ms);
 33→}
 34→
 35→/* Reveal lands at 75% opacity — hover brings to full */
